import csv
import io

# v1 used "available"; v2 of the Northgate feed has used other quantity headers.
QTY_COLUMNS = ("available", "quantity", "qty", "on_hand", "stock", "in_stock")
META_COLUMNS = {"sku", "updated_at"}


def parse_feed(text):
    reader = csv.DictReader(io.StringIO(text.lstrip("\ufeff")), skipinitialspace=True)
    if reader.fieldnames:
        reader.fieldnames = [(name or "").strip() for name in reader.fieldnames]
    qty_key = _quantity_column(reader.fieldnames or [])
    stock = {}
    for row in reader:
        sku = (row.get("sku") or "").strip()
        if not sku:
            continue
        stock[sku] = int(float(str(row[qty_key]).strip()))
    return stock


def _quantity_column(fieldnames):
    names = set(fieldnames)
    for key in QTY_COLUMNS:
        if key in names:
            return key
    extras = [name for name in fieldnames if name not in META_COLUMNS]
    if extras:
        return extras[0]
    raise ValueError(f"no quantity column in {fieldnames}")
