def _unescape_pdf_string(value):
    def _replace(match):
        escaped = match.group(1)
        return {
            "n": "\n",
            "r": "\r",
            "t": "\t",
            "b": "\b",
            "f": "\f",
            "(": "(",
            ")": ")",
            "\\": "\\",
        }.get(escaped, escaped)

    return re.sub(r"\\(.)", _replace, value)


def _pdf_text_from_bytes(pdf_bytes):
    """Extract Tj/TJ shown text from a simple FPDF document."""
    data = pdf_bytes.decode("latin-1")
    chunks = []
    for match in re.finditer(r"\((?:\\.|[^\\)])*\)\s*Tj", data):
        inner = match.group(0).rsplit("Tj", 1)[0].strip()[1:-1]
        chunks.append(_unescape_pdf_string(inner))
    for match in re.finditer(r"\[(.*?)\]\s*TJ", data, re.DOTALL):
        for inner in re.findall(r"\((?:\\.|[^\\)])*\)", match.group(1)):
            chunks.append(_unescape_pdf_string(inner[1:-1]))
    return "\n".join(chunks)


def _pdf_text(pdf_bytes, tmp_path):
    path = tmp_path / "confirmation.pdf"
    path.write_bytes(pdf_bytes)
    if shutil.which("pdftotext"):
        result = subprocess.run(
            ["pdftotext", "-layout", str(path), "-"],
            capture_output=True,
            text=True,
            check=True,
        )
        return result.stdout
    return _pdf_text_from_bytes(pdf_bytes)


def test_confirmation_names_patient_and_time(tmp_path):
    text = _pdf_text(render_confirmation(BOOKING), tmp_path)
    assert "Giulia Conti" in text
    assert "Monday 5 October 2026, 09:30" in text


def test_confirmation_explains_how_to_cancel(tmp_path):
    text = _pdf_text(render_confirmation(BOOKING), tmp_path)
    assert "24 hours" in text


def _qpdf_check(pdf_bytes, tmp_path):
    path = tmp_path / "confirmation.pdf"
    path.write_bytes(pdf_bytes)
    return subprocess.run(["qpdf", "--check", str(path)], capture_output=True, text=True)


def _structurally_valid_pdf(pdf_bytes):
    if not pdf_bytes.startswith(b"%PDF-"):
        return False
    if b"%%EOF" not in pdf_bytes[-2048:]:
        return False
    compact = pdf_bytes.replace(b" ", b"")
    has_page = b"/Type/Page" in compact
    has_font = b"/Font" in pdf_bytes
    return has_page and has_font


def test_confirmation_is_a_well_formed_pdf(tmp_path):
    pdf_bytes = render_confirmation(BOOKING)
