def _pdf_text_from_bytes(pdf_bytes):
    """Extract Tj/TJ shown text from a simple FPDF document."""
    data = pdf_bytes.decode("latin-1")
    chunks = []
    for match in re.finditer(r"\((?:\\.|[^\\)])*\)\s*Tj", data):
        inner = match.group(0).rsplit("Tj", 1)[0].strip()[1:-1]
        chunks.append(_unescape_pdf_string(inner))
    for match in re.finditer(r"\[(.*?)\]\s*TJ", data, re.DOTALL):
        for inner in re.findall(r"\((?:\\.|[^\\)])*\)", match.group(1)):
