"""Minimal pdftotext stand-in for confirmation PDF checks."""
import re
import sys
from pathlib import Path


def unescape(value):
    def replace(match):
        escaped = match.group(1)
        return {
            "n": "\n",
            "r": "\r",
            "t": "\t",
            "b": "\b",
            "f": "\f",
            "(": "(",
            ")": ")",
            "\\": "\\",
        }.get(escaped, escaped)

    return re.sub(r"\\(.)", replace, value)


def pdf_text(data):
    raw = data.decode("latin-1")
    chunks = []
    for match in re.finditer(r"\((?:\\.|[^\\)])*\)\s*Tj", raw):
        inner = match.group(0).rsplit("Tj", 1)[0].strip()[1:-1]
        chunks.append(unescape(inner))
    for match in re.finditer(r"\[(.*?)\]\s*TJ", raw, re.DOTALL):
        for inner in re.findall(r"\((?:\\.|[^\\)])*\)", match.group(1)):
            chunks.append(unescape(inner[1:-1]))
    return "\n".join(chunks) + "\n"


def main(argv):
    args = [a for a in argv[1:] if a != "-layout"]
    if not args:
        return 2
    pdf_path = args[0]
    out_path = args[1] if len(args) > 1 else None
    text = pdf_text(Path(pdf_path).read_bytes())
    if out_path in (None, "-"):
        sys.stdout.write(text)
    else:
        Path(out_path).write_text(text)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
