def _unescape_pdf_string(s):
    def repl(m):
        esc = m.group(0)
        mapping = {
            b"\\n": b"\n",
            b"\\r": b"\r",
            b"\\t": b"\t",
            b"\\b": b"\b",
            b"\\f": b"\f",
            b"\\(": b"(",
            b"\\)": b")",
            b"\\\\": b"\\",
        }
        if esc in mapping:
            return mapping[esc]
        if esc.startswith(b"\\") and esc[1:].isdigit():
            return bytes([int(esc[1:], 8)])
        return esc[1:]

    s = re.sub(rb"\\[nrtbf()\\]|\\[0-7]{1,3}", repl, s)
    return s.decode("latin-1")


def _content_streams(pdf_bytes):
    streams = []
    for m in re.finditer(rb"stream\r?\n(.*?)(?:\r?\n)endstream", pdf_bytes, re.DOTALL):
        data = m.group(1)
        try:
            data = zlib.decompress(data)
        except zlib.error:
            pass
        streams.append(data)
    return streams


def _pdf_text(pdf_bytes):
    parts = []
    for data in _content_streams(pdf_bytes):
        for m in re.finditer(rb"\(((?:\\.|[^\\)])*)\)\s*Tj", data):
            parts.append(_unescape_pdf_string(m.group(1)))
        for m in re.finditer(rb"\[(.*?)\]\s*TJ", data, re.DOTALL):
            for sm in re.finditer(rb"\(((?:\\.|[^\\)])*)\)", m.group(1)):
                parts.append(_unescape_pdf_string(sm.group(1)))
    return "\n".join(parts)


