    assert "24 hours" in text


def _qpdf_style_check(pdf_bytes):
    if not pdf_bytes.startswith(b"%PDF-"):
        return False, "missing %PDF- header"
    tail = pdf_bytes.rstrip(b"\r\n \t")
    if not tail.endswith(b"%%EOF"):
        return False, "missing %%EOF"
    matches = list(re.finditer(rb"startxref\s+(\d+)", pdf_bytes))
    if not matches:
        return False, "missing startxref"
    offset = int(matches[-1].group(1))
    at = pdf_bytes[offset : offset + 20]
    if not (at.startswith(b"xref") or re.match(rb"\d+\s+\d+\s+obj", at)):
        return False, f"startxref offset {offset} does not point to xref"
    for m in re.finditer(rb"/Filter\s*/FlateDecode", pdf_bytes):
        pass
    for data in re.finditer(rb"stream\r?\n(.*?)(?:\r?\n)endstream", pdf_bytes, re.DOTALL):
        chunk = data.group(1)
        try:
            zlib.decompress(chunk)
        except zlib.error:
            if chunk.startswith(b"x") or chunk.startswith(b"\x78"):
                return False, "flate stream did not decompress"
    return True, ""


def test_confirmation_is_a_well_formed_pdf():
    ok, reason = _qpdf_style_check(render_confirmation(BOOKING))
    assert ok, reason
