from datetime import datetime, time, timedelta

SLOT_MINUTES = 30
SLOT_LENGTH = timedelta(minutes=SLOT_MINUTES)

# Keys are datetime.date.weekday(): Monday=0 ... Sunday=6
OPENING_HOURS = {
    0: (time(8, 30), time(18, 0)),
    1: (time(8, 30), time(18, 0)),
    2: (time(8, 30), time(18, 0)),
    3: (time(8, 30), time(18, 0)),
    4: (time(8, 30), time(14, 0)),
}


def slots_for(day):
    hours = OPENING_HOURS.get(day.weekday())
    if hours is None:
        return []
    start, end = (datetime.combine(day, t) for t in hours)
    slots = []
    while start + SLOT_LENGTH <= end:
        slots.append(start)
        start += SLOT_LENGTH
    return slots
