def _pdf_text(pdf_bytes):
    chunks = []
    for match in re.finditer(rb"stream\r?\n(.+?)\r?\nendstream", pdf_bytes, re.DOTALL):
        data = match.group(1)
        try:
            data = zlib.decompress(data)
